def validate(r):
    source=r["measured_candidate"]["commit"]
    assert len(source)==40 and all(c in "0123456789abcdef" for c in source)
    tree=subprocess.check_output(["git","rev-parse",source+"^{tree}"],text=True).strip()
    assert r["measured_candidate"]["tree"]==tree
    for asset in r["assets"]:
        data=(root/asset["Git_path"]).read_bytes()
        assert len(data)==asset["bytes"]
        assert hashlib.sha256(data).hexdigest()==asset["sha256"]
    for name, folder in [("unpatched","root-composed-frc"),("isolated_A_packet_overlay","root-composed-frc-overlay")]:
        cases=list(ET.parse(p.parent/folder/"pytest.xml").getroot().iter("testcase"))
        actual={"total":len(cases),"PASS":sum(c.find("failure") is None and c.find("error") is None and c.find("skipped") is None for c in cases),"FAIL":sum(c.find("failure") is not None for c in cases),"ERROR":sum(c.find("error") is not None for c in cases),"SKIP":sum(c.find("skipped") is not None for c in cases)}
        assert r["consumer_checks"][name]==actual
